INSERT INTO `hotfixes`.`spell` (`ID`, `NameSubtext`, `Description`, `AuraDescription`, `VerifiedBuild`) VALUES
(7302509, '', 'Your |cffffffffCrypt Fiend|r deals ${$302509m1+$302509ppl1+$sps*0.5} Shadow Damage to it''s target and reduces their movement speed by $302539s1% for $302511d. Damage dealt pierces through all absorption effects and cannot be resisted.', 'Your |cffffffffCrypt Fiend|r deals ${$302509m1+$302509ppl1+$sps*0.5} Shadow Damage to it''s target and reduces their movement speed by $302539s1% for $302511d. Damage dealt pierces through all absorption effects and cannot be resisted.', 69933),
(7302517, 'Tomb King/Bone Wraith', '', 'Your next $?s805044[Animate: Tomb King][]$?s805032[|cffffffffAnimate: Bone Wraith|r][] is free of cost and will incur no cooldown.', 69933),
(7302912, 'Zombie TRIGGER', '', '', 69933),
(7302913, 'Temp Summon low Duration (for procs/triggers/talents)', 'summon a baby zombie to do his thang', 'summon a baby zombie to do his thang', 69933),
(7500327, '', 'Explode, destroying the Rotling and causing Plague Damage to all nearby enemies.', 'Explode, destroying the Rotling and causing Plague Damage to all nearby enemies.', 69933),
(7500328, '', 'Explode, destroying the Rotling and causing Plague Damage to all nearby enemies.', 'Explode, destroying the Rotling and causing Plague Damage to all nearby enemies.', 69933),
(7500585, '', 'Explode, destroying the Rotling and causing Plague Damage to all nearby enemies.', 'Explode, destroying the Rotling and causing Plague Damage to all nearby enemies.', 69933),
(7500729, '', '', 'Invulnerable to damage, Movement Speed increased by ${$w2}%, unable to attack or cast spells.
